inline bool SupportedCode()
{
    for (const auto& guard : codeGuards)
    {
        auto module = GetModuleHandleW(guard.module);
        if (!module || !Readable(module, sizeof(IMAGE_DOS_HEADER))) return false;
        auto dos = reinterpret_cast<const IMAGE_DOS_HEADER*>(module);
        if (dos->e_magic != IMAGE_DOS_SIGNATURE || dos->e_lfanew < 0 || dos->e_lfanew > 4096) return false;
        auto nt = reinterpret_cast<const IMAGE_NT_HEADERS*>(reinterpret_cast<const unsigned char*>(module) + dos->e_lfanew);
        if (!Readable(nt, sizeof(*nt)) || nt->Signature != IMAGE_NT_SIGNATURE ||
            guard.rva > nt->OptionalHeader.SizeOfImage || guard.bytes.size() > nt->OptionalHeader.SizeOfImage - guard.rva) return false;
        auto target = reinterpret_cast<const unsigned char*>(module) + guard.rva;
        if (!Readable(target, guard.bytes.size())) return false;
        for (size_t i = 0; i < guard.bytes.size(); ++i)
            if ((target[i] & guard.mask[i]) != (guard.bytes[i] & guard.mask[i])) return false;
    }
    for (const auto& guard : tableGuards)
    {
        auto module = GetModuleHandleW(guard.module);
        if (!module) return false;
        auto entry = reinterpret_cast<const unsigned char*>(module) + guard.entry;
        if (!Readable(entry, sizeof(uintptr_t))) return false;
        uintptr_t target{}; std::memcpy(&target, entry, sizeof(target));
        if (target != reinterpret_cast<uintptr_t>(module) + guard.target) return false;
    }
    return true;
}
